import React from 'react';
import FeatherIcon from 'feather-icons-react';

const CaptchaVrPost = ({ post }) => {
    const { articleContent } = post;

    const Chart = ({ title, subtitle, valueKey, max, suffix, note }) => (
        <article className="cvr-chart-card">
            <div className="cvr-chart-heading"><h3>{title}</h3><span>{subtitle}</span></div>
            <div className="cvr-chart-rows">
                {articleContent.results.map(result => {
                    const value = result[valueKey];
                    return (
                        <div className="cvr-chart-row" key={`${valueKey}-${result.id}`}>
                            <div className="cvr-chart-label">{result.name}</div>
                            <div className="cvr-chart-track">
                                <div className={`cvr-chart-fill ${result.id} ${valueKey === 'success' && result.completion ? 'is-completion' : ''}`} style={{ width: `${Math.max((value / max) * 100, 4)}%` }} />
                            </div>
                            <strong>{value.toFixed(1)}{suffix}</strong>
                            {valueKey === 'success' && <small>{result.successLabel}</small>}
                        </div>
                    );
                })}
            </div>
            {note && <p className="cvr-chart-note"><FeatherIcon icon="info" />{note}</p>}
        </article>
    );

    return (
        <div className="cvr-article">
            <style>{`
                .cvr-article { --cvr-wine: #8b0029; --cvr-navy: #192532; --cvr-teal: #188d8b; --cvr-ink: #20252c; color: var(--cvr-ink); }
                .cvr-hero { overflow: hidden; border: 1px solid rgba(139,0,41,.12); border-radius: 28px; background: #1d2430; }
                .cvr-hero img { display: block; width: 100%; height: auto; aspect-ratio: 16 / 9; object-fit: cover; }
                .cvr-section { margin-top: 30px; padding: clamp(24px,3vw,38px); border: 1px solid #e8ebef; border-radius: 28px; background: #fff; }
                .cvr-heading { max-width: 980px; margin: 0 auto 28px; text-align: center; }
                .cvr-heading > span { color: var(--cvr-wine); font-size: .75rem; font-weight: 900; letter-spacing: .12em; text-transform: uppercase; }
                .cvr-heading h2 { margin: 9px 0 10px; font-size: clamp(1.8rem,3.5vw,2.65rem); font-weight: 900; letter-spacing: -.045em; }
                .cvr-heading p { margin: 0; color: #65707b; line-height: 1.8; }
                .cvr-lead { max-width: 1080px; margin: 0 auto; font-size: 1.1rem; line-height: 1.95; text-align: center; word-break: keep-all; }
                .cvr-question-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; margin-top: 28px; }
                .cvr-question { padding: 22px; border: 1px solid #e7eaee; border-radius: 19px; background: #f8fafb; }
                .cvr-question small { color: var(--cvr-teal); font-size: .7rem; font-weight: 900; letter-spacing: .1em; }
                .cvr-question h3 { margin: 17px 0 0; font-size: 1.08rem; line-height: 1.55; font-weight: 850; }
                .cvr-story-section { background: #f7f8fa; }
                .cvr-story-list { display: grid; gap: 16px; }
                .cvr-story-card { display: grid; grid-template-columns: 76px minmax(0,1fr); gap: 20px; padding: 25px; border: 1px solid #e4e8ec; border-radius: 22px; background: #fff; }
                .cvr-story-index { width: 56px; height: 56px; display: grid; place-items: center; border-radius: 18px; background: var(--cvr-navy); color: #fff; font-weight: 900; }
                .cvr-story-card small { color: var(--cvr-wine); font-size: .75rem; font-weight: 900; letter-spacing: .1em; text-transform: uppercase; }
                .cvr-story-card h3 { margin: 6px 0 17px; font-size: clamp(1.45rem,2.6vw,2rem); font-weight: 900; letter-spacing: -.035em; }
                .cvr-story-card p { margin: 0 0 14px; color: #515962; font-size: 1.01rem; line-height: 1.9; text-align: justify; word-break: keep-all; }
                .cvr-story-card p:last-of-type { margin-bottom: 0; }
                .cvr-story-card blockquote { margin: 22px 0 0; padding: 16px 19px; border-left: 4px solid var(--cvr-teal); border-radius: 0 12px 12px 0; background: #f2f8f8; color: #176b6a; font-weight: 850; line-height: 1.65; }
                .cvr-chart-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
                .cvr-chart-card { padding: 22px; border: 1px solid #e4e8ec; border-radius: 20px; background: #fbfcfd; }
                .cvr-chart-heading h3 { margin: 0; font-size: 1.1rem; font-weight: 900; }
                .cvr-chart-heading span { color: #7b858e; font-size: .74rem; }
                .cvr-chart-rows { display: grid; gap: 15px; margin-top: 22px; }
                .cvr-chart-row { display: grid; grid-template-columns: 78px 1fr 52px; gap: 8px; align-items: center; }
                .cvr-chart-label { font-size: .75rem; font-weight: 850; }
                .cvr-chart-track { height: 11px; overflow: hidden; border-radius: 999px; background: #e7ebee; }
                .cvr-chart-fill { height: 100%; border-radius: 999px; background: var(--cvr-wine); }
                .cvr-chart-fill.hearing { background: var(--cvr-teal); }
                .cvr-chart-fill.is-completion { background: repeating-linear-gradient(135deg,#8b0029 0 7px,#c76a85 7px 14px); }
                .cvr-chart-row strong { font-size: .78rem; text-align: right; }
                .cvr-chart-row > small { grid-column: 2 / 4; margin-top: -7px; color: #879098; font-size: .64rem; }
                .cvr-chart-note { display: flex; gap: 7px; margin: 18px 0 0; color: #6d7780; font-size: .72rem; line-height: 1.55; }
                .cvr-chart-note svg { flex: 0 0 17px; width: 17px; height: 17px; color: var(--cvr-wine); }
                .cvr-result-summary { margin: 20px 0 0; padding: 17px 20px; border-left: 4px solid var(--cvr-teal); border-radius: 0 14px 14px 0; background: #f2f8f8; color: #465b5d; line-height: 1.7; }
                .cvr-attack { background: #f6f2f4; }
                .cvr-attack-flow { display: grid; grid-template-columns: repeat(3,1fr); gap: 14px; }
                .cvr-attack-card { padding: 25px; border: 1px solid #e3d9dd; border-radius: 20px; background: #fff; }
                .cvr-attack-card small { color: var(--cvr-wine); font-weight: 900; }
                .cvr-attack-card strong { display: block; margin: 13px 0 9px; font-size: 1.75rem; }
                .cvr-attack-card p { margin: 0; color: #68717a; font-size: .88rem; line-height: 1.65; }
                .cvr-attack-card.risk { border-color: rgba(139,0,41,.35); }
                .cvr-attack-card.changed { border-color: rgba(24,141,139,.38); }
                .cvr-caveat { display: flex; gap: 10px; margin-top: 17px; padding: 15px 17px; border-radius: 14px; background: #fff; color: #68717a; font-size: .78rem; line-height: 1.65; }
                .cvr-caveat svg { flex: 0 0 19px; color: var(--cvr-wine); }
                .cvr-principles { display: grid; grid-template-columns: repeat(5,1fr); gap: 10px; }
                .cvr-principle { padding: 17px 12px; border: 1px solid #e6e9ec; border-radius: 15px; background: #fafbfc; text-align: center; }
                .cvr-principle span { display: block; color: var(--cvr-teal); font-size: .68rem; font-weight: 900; }
                .cvr-principle strong { display: block; margin-top: 6px; font-size: .83rem; }
                .cvr-takeaway { margin-top: 30px; padding: clamp(30px,4vw,48px) clamp(22px,3vw,38px); border-radius: 28px; background: var(--cvr-navy); color: #fff; text-align: center; }
                .cvr-takeaway h2 { margin: 0 0 16px; color: #fff; font-size: clamp(1.7rem,3.7vw,2.7rem); font-weight: 900; line-height: 1.35; letter-spacing: -.04em; }
                .cvr-takeaway p { margin: 0; color: rgba(255,255,255,.68); line-height: 1.85; }
                .cvr-publication { display: flex; justify-content: space-between; gap: 24px; align-items: center; margin-top: 30px; padding: 24px; border: 1px solid #e5e9ec; border-radius: 22px; background: #fff; }
                .cvr-publication small { color: var(--cvr-teal); font-weight: 900; letter-spacing: .08em; }
                .cvr-publication h3 { margin: 6px 0 8px; font-size: 1.12rem; font-weight: 900; }
                .cvr-publication p { margin: 0; color: #6b747d; font-size: .83rem; line-height: 1.6; }
                .cvr-publication a { flex: 0 0 auto; display: inline-flex; align-items: center; gap: 8px; padding: 12px 17px; border-radius: 999px; background: var(--cvr-wine); color: #fff; font-weight: 850; text-decoration: none; }
                @media (max-width: 1000px) { .cvr-chart-grid { grid-template-columns: repeat(2,1fr); } .cvr-attack-flow { grid-template-columns: 1fr; } .cvr-principles { grid-template-columns: repeat(2,1fr); } }
                @media (max-width: 650px) { .cvr-section, .cvr-hero { border-radius: 21px; } .cvr-question-grid, .cvr-chart-grid { grid-template-columns: 1fr; } .cvr-story-card { grid-template-columns: 1fr; padding: 21px; } .cvr-story-card p { text-align: left; } .cvr-principles { grid-template-columns: 1fr 1fr; } .cvr-publication { flex-direction: column; align-items: flex-start; } }
            `}</style>

            <header className="cvr-hero">
                <img src={post.image} alt="VR 공간에서 네 가지 3D CAPTCHA를 체험하는 사용자" />
                <div className="visually-hidden"><h1>{post.headline}</h1><p>{post.subtitle}</p></div>
            </header>

            <section className="cvr-section">
                <div className="cvr-heading"><span>Research Question</span><h2>VR에서 사람과 AI를 어떻게 구별할 수 있을까?</h2></div>
                <p className="cvr-lead">{articleContent.lead}</p>
                <div className="cvr-question-grid">
                    {articleContent.questions.map((question, index) => <div className="cvr-question" key={question}><small>QUESTION {String(index + 1).padStart(2, '0')}</small><h3>{question}</h3></div>)}
                </div>
            </section>

            <section className="cvr-section cvr-story-section">
                <div className="cvr-heading"><span>Research Story</span><h2>게임처럼 읽는 VR 보안 이야기</h2><p>익숙한 CAPTCHA가 어떻게 공간 속 미니게임으로 바뀌었는지 따라가 봅니다.</p></div>
                <div className="cvr-story-list">
                    {articleContent.storySections.map((story, index) => (
                        <article className="cvr-story-card" key={story.kicker}>
                            <div className="cvr-story-index">{String(index + 1).padStart(2, '0')}</div>
                            <div><small>{story.kicker}</small><h3>{story.title}</h3>{story.paragraphs.map((paragraph, pIndex) => <p key={pIndex}>{paragraph}</p>)}{story.quote && <blockquote>{story.quote}</blockquote>}</div>
                        </article>
                    ))}
                </div>
            </section>

            <section className="cvr-section">
                <div className="cvr-heading"><span>Experiment Results</span><h2>빠르고 편한 과제는 무엇이었을까?</h2><p>32명의 참가자가 수행한 네 가지 VR CAPTCHA의 실제 평균값입니다.</p></div>
                <div className="cvr-chart-grid">
                    <Chart title="평균 해결 시간" subtitle="낮을수록 빠름" valueKey="time" max={162} suffix="초" />
                    <Chart title="시스템 사용성" subtitle="SUS · 0–100점" valueKey="sus" max={100} suffix="" />
                    <Chart title="정확도와 완성도" subtitle="지표 정의에 주의" valueKey="success" max={100} suffix="%" note="Assembling의 71.1%는 정답률이 아니라 조립 완성도입니다. 다른 과제와 같은 척도로 단순 비교할 수 없습니다." />
                </div>
                <p className="cvr-result-summary">Hearing과 Gathering의 사용성은 Wayfinding과 Assembling보다 통계적으로 유의하게 높았습니다. 네 과제의 난이도가 동일하게 통제된 것은 아니므로 해결 시간만으로 과제 유형의 본질적 우열을 단정할 수는 없습니다.</p>
            </section>

            <section className="cvr-section cvr-attack">
                <div className="cvr-heading"><span>AI Attack Lab</span><h2>AI도 통과할 수 있을까?</h2><p>3D Wayfinding에 대한 개념검증 공격은 공격자가 가진 정보와 문제 구성의 중요성을 보여줍니다.</p></div>
                <div className="cvr-attack-flow">{articleContent.attackStages.map(stage => <article className={`cvr-attack-card ${stage.tone}`} key={stage.label}><small>{stage.label}</small><strong>{stage.value}</strong><p>{stage.body}</p></article>)}</div>
                <div className="cvr-caveat"><FeatherIcon icon="alert-circle" /><span>위 수치는 특정 강화학습 모델과 실험 조건의 결과이며 일반적인 공격 성공률을 뜻하지 않습니다. 논문은 Assembling과 Hearing에 대한 별도의 AI 자동 공격 분석을 수행하지 않았습니다.</span></div>
            </section>

            <section className="cvr-section">
                <div className="cvr-heading"><span>Design Principles</span><h2>VR CAPTCHA를 위한 열 가지 원칙</h2><p>보안성과 사용성은 함께 설계되어야 합니다.</p></div>
                <div className="cvr-principles">{articleContent.principles.map((principle, index) => <div className="cvr-principle" key={principle}><span>{String(index + 1).padStart(2, '0')}</span><strong>{principle}</strong></div>)}</div>
            </section>

            <section className="cvr-takeaway"><h2>“{articleContent.takeaway.title}”</h2><p>{articleContent.takeaway.body}</p></section>

            <section className="cvr-publication">
                <div><small>PUBLICATION</small><h3>{post.paperTitle}</h3><p>{post.authors}<br />{post.journal} · {post.details}</p></div>
                <a href={post.paperUrl} target="_blank" rel="noopener noreferrer">논문 바로가기 <FeatherIcon icon="external-link" size={18} /></a>
            </section>
        </div>
    );
};

export default CaptchaVrPost;
