import React, { useEffect, useRef, useState } from 'react';
import ReactDOM from 'react-dom';
import FeatherIcon from 'feather-icons-react';
import './WinterInternshipPopup.css';

const DISMISS_KEY = 'imx-winter-internship-popup-dismissed-date-v1';

function getTodayKey() {
    const now = new Date();
    const offset = now.getTimezoneOffset() * 60 * 1000;
    return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

function WinterInternshipPopup() {
    const [isOpen, setIsOpen] = useState(false);
    const [position, setPosition] = useState(null);
    const popupRef = useRef(null);
    const dragRef = useRef(null);

    useEffect(() => {
        let dismissedToday = false;

        try {
            dismissedToday = localStorage.getItem(DISMISS_KEY) === getTodayKey();
        } catch (error) {
            // Keep showing the notice when browser storage is unavailable.
        }

        if (!dismissedToday) {
            const openTimer = window.setTimeout(() => setIsOpen(true), 550);
            return () => window.clearTimeout(openTimer);
        }

        return undefined;
    }, []);

    useEffect(() => {
        if (!isOpen) return undefined;

        const handleKeyDown = (event) => {
            if (event.key === 'Escape') setIsOpen(false);
        };

        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [isOpen]);

    const startDragging = (event) => {
        if (event.button !== 0 || window.innerWidth <= 767 || event.target.closest('button')) return;

        const popupBounds = popupRef.current.getBoundingClientRect();
        dragRef.current = {
            offsetX: event.clientX - popupBounds.left,
            offsetY: event.clientY - popupBounds.top
        };
        event.currentTarget.setPointerCapture(event.pointerId);
    };

    const dragPopup = (event) => {
        if (!dragRef.current || !popupRef.current) return;

        const popupBounds = popupRef.current.getBoundingClientRect();
        const left = Math.min(
            Math.max(8, event.clientX - dragRef.current.offsetX),
            window.innerWidth - popupBounds.width - 8
        );
        const top = Math.min(
            Math.max(8, event.clientY - dragRef.current.offsetY),
            window.innerHeight - Math.min(popupBounds.height, window.innerHeight - 16) - 8
        );

        setPosition({ left, top });
    };

    const stopDragging = (event) => {
        dragRef.current = null;
        if (event.currentTarget.hasPointerCapture(event.pointerId)) {
            event.currentTarget.releasePointerCapture(event.pointerId);
        }
    };

    const dismissForToday = () => {
        try {
            localStorage.setItem(DISMISS_KEY, getTodayKey());
        } catch (error) {
            // Closing is still allowed when browser storage is unavailable.
        }
        setIsOpen(false);
    };

    if (!isOpen) return null;

    return ReactDOM.createPortal(
        <div className="winter-intern-popup-layer" role="presentation">
            <section
                ref={popupRef}
                className="winter-intern-popup"
                role="dialog"
                aria-modal="false"
                aria-labelledby="winter-intern-popup-title"
                style={position ? { left: `${position.left}px`, top: `${position.top}px` } : undefined}
            >
                <div
                    className="winter-intern-popup-windowbar"
                    onPointerDown={startDragging}
                    onPointerMove={dragPopup}
                    onPointerUp={stopDragging}
                    onPointerCancel={stopDragging}
                >
                    <div className="winter-intern-popup-windowdots" aria-hidden="true">
                        <span /><span /><span />
                    </div>
                    <span className="winter-intern-popup-windowtitle">IMX LAB · OPEN POSITION</span>
                    <button
                        type="button"
                        className="winter-intern-popup-close"
                        aria-label="겨울방학 인턴 모집 공고 닫기"
                        onClick={() => setIsOpen(false)}
                    >
                        <FeatherIcon icon="x" size="21" />
                    </button>
                </div>

                <div className="winter-intern-popup-hero">
                    <div className="winter-intern-popup-orb winter-intern-popup-orb-one" aria-hidden="true" />
                    <div className="winter-intern-popup-orb winter-intern-popup-orb-two" aria-hidden="true" />
                    <div className="winter-intern-popup-grid" aria-hidden="true" />

                    <div className="winter-intern-popup-kicker">
                        WINTER RESEARCH INTERNSHIP
                    </div>
                    <h2 id="winter-intern-popup-title">
                        2026–2027 겨울방학<br />
                        <span>실전 연구 인턴 모집</span>
                    </h2>
                    <div className="winter-intern-popup-topic-tags" aria-label="연구 분야">
                        <span>XR</span>
                        <span>GAME</span>
                        <span>AI</span>
                        <span>YOUR IDEA</span>
                    </div>
                </div>

                <div className="winter-intern-popup-body">
                    <div className="winter-intern-popup-highlights">
                        <article>
                            <div>
                                <small>PERSONAL WORKSTATION</small>
                                <strong>RTX 5080 GPU 개인 PC 제공</strong>
                            </div>
                        </article>
                        <article>
                            <div>
                                <small>OPEN RESEARCH TOPIC</small>
                                <strong>XR · 게임 · AI 등 자유 연구</strong>
                            </div>
                        </article>
                        <article className="winter-intern-popup-goal">
                            <div>
                                <small>RESEARCH GOAL</small>
                                <strong>2027년 3월 말 국제 학회 논문 제출 목표</strong>
                            </div>
                        </article>
                    </div>
                    <div className="winter-intern-popup-requirement">
                        <span className="winter-intern-popup-requirement-label">필수 요건</span>
                        <span className="winter-intern-popup-requirement-text">
                            방학 기간 연구실 주 3일 이상 상주할 것
                        </span>
                    </div>

                </div>

                <div className="winter-intern-popup-footer">
                    <button type="button" onClick={dismissForToday}>오늘 하루 보지 않기</button>
                </div>
            </section>
        </div>,
        document.body
    );
}

export default WinterInternshipPopup;
