import React from 'react';
import { HashRouter as Router, Switch, Route } from 'react-router-dom';
import './App.css';

// 공용 컴포넌트

// 페이지 컴포넌트 (실제 파일 경로에 맞게 수정 필요)
import Home from './pages/home';
import Team from './pages/Team';
import Research from './pages/Research';
import Projects from './pages/Project';
import Publications from './pages/Publication';
import Posts from './pages/Post';
import Lectures from './pages/Course';
import News from './pages/News';
import Gallery from './pages/Gallery';
import JoinUs from './pages/JoinUs';
import JoinUsTest from './pages/JoinUsTest';
import NotFound from './pages/NotFound'; // 404 페이지가 있다면 추가
import ProfessorProfile from './pages/ProfessorProfile';
import PublicationDetail from './pages/PublicationDetail';
import PostDetail from './pages/PostDetail';
import TopNav from './components/TopNav';
import Footer from './components/Footer';

function App() {
  return (
    <Router>
      <TopNav />
      
      {/* 페이지 콘텐츠 */}
      <main>
        <Switch>
          <Route exact path="/" component={Home} />
          <Route path="/team/prof-hanseob-kim" component={ProfessorProfile} />
          <Route path="/publication/:id" component={PublicationDetail} />
          <Route path="/post/:id" component={PostDetail} />
          <Route exact path="/team" component={Team} />
          <Route exact path="/research" component={Research} />
          <Route exact path="/project" component={Projects} />
          <Route exact path="/publication" component={Publications} />
          <Route exact path="/post" component={Posts} />
          <Route exact path="/course" component={Lectures} />
          <Route exact path="/news" component={News} />
          <Route exact path="/gallery" component={Gallery} />
          <Route exact path="/join-us-test" component={JoinUs} />
          <Route exact path="/join-us" component={JoinUsTest} />
          {/* 일치하는 경로가 없을 때 보여줄 페이지 */}
          <Route component={NotFound} /> 
        </Switch>
      </main>
      <Footer />
    </Router>
  );
}

export default App;
